import { Vector3 } from "@babylonjs/core/Maths/math.vector";
import type { Scene } from "@babylonjs/core/scene";
import { visibleAsBoolean, visibleAsNumber, visibleAsString, visibleAsVector3, type IScript } from "babylonjs-editor-tools";
import { createNativeSliceRuntime } from "../runtime/createNativeSliceRuntime";
import { isSceneStartupRequired, registerSceneStartup, reportSceneStartup } from "../scene/prepareSceneForReveal";
import { showLoadingError } from "../ui/LoadingScreen";

/** Authored values are saved in the Editor scene, never generated by migration. */
export default class NativeParityScript implements IScript {
  @visibleAsString("Player profile") playerProfileId = "human-male-fighter";
  @visibleAsBoolean("Start with Leather Shirt (item 22)") leatherShirt = false;
  @visibleAsVector3("Synthetic actor origin") origin = Vector3.Zero();
  @visibleAsString("Fighter idle clip") fighterIdle = "Wait_Hand_MFighter";
  @visibleAsString("Fighter run clip") fighterRun = "Run_Hand_MFighter";
  @visibleAsString("Fighter attack clip") fighterAttack = "Atk01_Hand_MFighter";
  @visibleAsString("Fighter death clip") fighterDeath = "Death_MFighter";
  @visibleAsBoolean("Enable material override", { group: "Native material" }) materialOverrideEnabled = false;
  @visibleAsString("Actor ID", { group: "Native material" }) materialEntityId = "local-player";
  @visibleAsString("Source material", { group: "Native material" }) materialSource = "MFighter.UpBody.MFighter_m001_t04_u";
  // Editor 5.5.3's script RGB numeric controls omit their commit callback.
  // Its vector fields persist all three components through the normal UI.
  @visibleAsVector3("Tint RGB multiplier", { group: "Native material", min: 0, max: 1, step: .01,
    description: "Linear RGB multipliers on the original material. Converted textures remain unchanged." }) materialTint = Vector3.One();
  @visibleAsNumber("Roughness", { group: "Native material", min: 0, max: 1, step: .01 }) materialRoughness = 1;
  @visibleAsBoolean("Enable source flame preview", { group: "Flame replay",
    description: "Recovered source formulas; native lighting and clock synchronization remain unverified." }) flamePreviewEnabled = true;
  @visibleAsNumber("Texture start seconds", { group: "Flame replay", min: 0, step: .01 }) flameTextureSeconds = 0;
  @visibleAsNumber("Fade start seconds", { group: "Flame replay", min: 0, step: .01 }) flameFadeSeconds = 0;
  @visibleAsNumber("Texture replay rate", { group: "Flame replay", min: 0, step: .1 }) flameTextureRate = 1;
  @visibleAsNumber("Fade replay rate", { group: "Flame replay", min: 0, step: .1 }) flameFadeRate = 1;
  private lifetime: AbortController | undefined;
  private stop: (() => void) | undefined;
  constructor(private readonly scene: Scene) {}
  onStart(): void {
    this.onStop();
    // The pinned Editor packer serializes its default left-handed scene.
    // Establish this native scene's coordinates after parsing, before any
    // native GLB loader can insert a handedness conversion root.
    this.scene.useRightHandedSystem = true;
    const lifetime = new AbortController();
    this.lifetime = lifetime;
    // Capture this start's owner: an older pending load may settle after a restart.
    const required = isSceneStartupRequired(this.scene, "native-world");
    const ready = createNativeSliceRuntime(this.scene, this, lifetime.signal, {
      requireWorld: required,
      onProgress: progress => reportSceneStartup(this.scene, progress),
    }).then(stop => {
      if (lifetime.signal.aborted || this.lifetime !== lifetime) {
        stop(); throw new Error("Native scene startup was cancelled.");
      }
      this.stop = stop;
    });
    registerSceneStartup(this.scene, "native-world", ready);
    void ready.catch((error: unknown) => {
      if (!lifetime.signal.aborted && this.lifetime === lifetime) {
        // The app owns its actionable loading/error panel. Editor Play has no
        // App, so retain a visible error there without destroying panel markup.
        if (!required) { console.error(error); showLoadingError(error); }
      }
    });
  }
  onStop(): void {
    const lifetime = this.lifetime, stop = this.stop;
    this.lifetime = undefined; this.stop = undefined;
    lifetime?.abort(); stop?.();
  }
}
